  public function executeUpdate()
  {
    if (!$this->getRequestParameter('procedimiento_id'))
    {
      $procedimiento = new Procedimiento();
      $procedimiento->setFechaCreacion(date("Y-m-d G:i:s"));
      $old_files = false;
      $txt_oldfiles = "";
    }
    else
    {
      $procedimiento = ProcedimientoPeer::retrieveByPk($this->getRequestParameter('procedimiento_id'));
      $old_files = true;
      $txt_oldfiles = $procedimiento->getRuta();
      $this->forward404Unless($procedimiento);
    }
    //*****************************************************************************************************
    $procedimiento_anterior=$procedimiento->copy();			
	$usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
	$usernameloguiado = $this->getUser()->getAttribute('username', '', 'subscriber');
    //*****************************************************************************************************
    $procedimiento->setUsuarioId($usuariologuiado);
    $procedimiento->setTipoprocedimientoId($this->getRequestParameter('tipoprocedimiento_id') ? $this->getRequestParameter('tipoprocedimiento_id') : null);
    $procedimiento->setDependenciaId($this->getRequestParameter('dependencia_id') ? $this->getRequestParameter('dependencia_id') : null);
    $procedimiento->setCodigo($this->getRequestParameter('codigo'));
    $procedimiento->setNombre($this->getRequestParameter('nombre'));
    $procedimiento->setDescripcion($this->getRequestParameter('descripcion'));
    $procedimiento->setExtension($this->getRequestParameter('extension'));
    //*****************************************************************************************************
    $str_files = trim($this->getRequestParameter('archivo'));
    $procedimiento->setRuta($this->resolveUrlAttachment($str_files,$old_files,$txt_oldfiles));
    //*****************************************************************************************************
    if($this->getRequestParameter('procedimiento_id')!= '' || $this->getRequestParameter('idProce') != ''){
	    if($this->getRequestParameter('version') != ''){
	    	$temp = $this->getRequestParameter('version');
			$vca = $temp+1;				            	    	    	  
		  	$procedimiento->setVersion($vca);			  		  		  		  	
	    }
	}else{
		$procedimiento->setVersion(1);
	}
    //*****************************************************************************************************    
    if($this->getRequestParameter('codVer')){
    	$procedimiento->setCodigoVersion($this->getRequestParameter('codVer'));
    	$procedimiento->setEsUltimaVersion(true);
    	if($this->getRequestParameter('procedimiento_id')){
    	  $copia_procedimiento  = $procedimiento->copy();
    	  $copia_procedimiento->save();
		  $this->actualizarVersion($this->getRequestParameter('procedimiento_id'));
		}else{
			$procedimiento->save();
		}    	
    }else{
    	$procedimiento->save();
		$this->versionForma($procedimiento->getPrimaryKey());		   	
	}
    //*****************************************************************************************************
	if($this->getRequestParameter('idProce')){
	  $this->actualizarVersion($this->getRequestParameter('idProce'));
	}
	//*****************************************************************************************************
	$this->guardarAuditoria($procedimiento_anterior,$procedimiento);
    return $this->redirect($this->getRequest()->getScriptName().'/formas/show?procedimiento_id='.$procedimiento->getPrimaryKey());
  }

